/* ════════════════════════════════════════════════════════════════════════════
   خادم المنصة على Cloudflare — ملف واحد (‎_worker.js) بجانب index.html
   ────────────────────────────────────────────────────────────────────────────
   ماذا يفعل؟
   ① يقدّم ملف المنصة نفسه، وقبل تسليمه يحقن window.__BS_BOOT — تماماً كما
      يفعل خادم الجهاز المحلي — فتعمل طبقة التخزين الموجودة في المنصة أصلاً
      بلا أي تغيير: القراءات من الذاكرة، والكتابات إلى POST /api/save.
   ② بيانات الفريق كلها نسخة واحدة في قاعدة D1 (جداول مجزّأة chunked حتى لا
      يصطدم مفتاح كبير بحدود حجم الصف).
   ③ تسجيل دخول حقيقي: التحقق هنا في الخادم ضد بصمات كلمات المرور
      (PBKDF2-SHA256 — نفس صيغة المنصة p2$…، مع دعم الصيغة القديمة p1$…)،
      وجلسة بكوكي HttpOnly لا تصلها يد جافاسكربت، وعمرها نفس سياسة المنصة:
      ١٢ ساعة كحد أقصى وساعتا خمول.
   ④ مخزن الحسابات bassam_auth_users_v1 يُقدَّم للمتصفحات دائماً بلا حقل ph
      (البصمات لا تغادر الخادم)، وعند حفظه القادم من المتصفح تُدمَج البصمات
      المخزونة في السجلات التي وصلت بلا ph — فتغيير كلمة مرور يمرّ، وسرقة
      البصمات من متصفح موظف لا تحدث.
   ⑤ مفاتيح خاصة بالجهاز (الجلسة، حارس المحاولات، السمة، الإدارة النشطة)
      لا تُخزَّن مركزياً إطلاقاً — لكل جهاز حاله، كأي موقع محترم.
   ⑥ صور المنصة عبر ‎/api/img/* بنفس بروتوكول خادم الجهاز حرفياً.
   ════════════════════════════════════════════════════════════════════════════ */

/* ── الثوابت ── */
var K_USERS = 'bassam_auth_users_v1';
var SESSION_MAX = 12 * 3600 * 1000;      /* عمر الجلسة الأقصى — كسياسة المنصة (يُستبدل بالسياسة المضبوطة) */
var IDLE_MAX    = 2  * 3600 * 1000;      /* الخمول الأقصى */
var LOCK_N = 5;                           /* محاولات قبل القفل */
var LOCK_MS = 300000;                     /* أقصى مدة قفل */
var PRESENCE_MS = 120000;                 /* «نشط الآن» = تفاعل خلال دقيقتين */
/* ═══ سياسات الأمن القابلة للضبط من شاشة مدير النظام — تُقرأ مرةً لكل طلب ═══ */
var POLICY_DEF = { sessH: 12, idleH: 2, lockN: 5, lockMin: 5, pwMin: 6 };
async function loadPolicy(env) {
  var p = parseJson(await metaGet(env, 'policy'), null);
  var o = Object.assign({}, POLICY_DEF, isObj(p) ? p : {});
  SESSION_MAX = Math.max(1, +o.sessH || 12) * 3600000; IDLE_MAX = Math.max(0.25, +o.idleH || 2) * 3600000;
  LOCK_N = Math.max(3, +o.lockN || 5); LOCK_MS = Math.max(1, +o.lockMin || 5) * 60000; PW_MIN = Math.max(6, +o.pwMin || 6);
  return o;
}
/* ═══ سجل أحداث الأمن — منفصل عن تدقيق البيانات ═══
   act: login_ok · login_fail · lock · logout · sess_kill · pw_change · acct_add · acct_del · acct_freeze · acct_unfreeze ·
        perm_change · denied · policy_change · guard_unlock · admin */
function secStmt(env, e) {
  return env.DB.prepare('INSERT INTO sec (ts, uid, un, act, target, detail, ip, city, dev) VALUES (?1, ?2, ?3, ?4, ?5, ?6, ?7, ?8, ?9)')
    .bind(e.ts || Date.now(), e.uid || '', e.un || '', e.act, e.target || '', e.detail == null ? '' : String(e.detail).slice(0, 600), e.ip || '', e.city || '', e.dev || '');
}
async function secLog(env, e) { try { await secStmt(env, e).run(); } catch (x) {} }
function reqMeta(request) {
  var cf = request.cf || {};
  var ua = request.headers.get('User-Agent') || '';
  var dev = /Mobi|Android|iPhone|iPad/i.test(ua) ? 'm' : 'd';
  var city = [cf.city, cf.country].filter(Boolean).join(' · ');
  return { ip: request.headers.get('CF-Connecting-IP') || '', city: city, dev: dev, ua: ua.slice(0, 200) };
}
var CHUNK = 700000;                       /* حجم قطعة التخزين للقيم الكبيرة */
var COOKIE = 'bs_tok';
/* مفاتيح جهازٍ لا فريق: لا تُقبل حفظاً ولا تُحقن — لكل متصفح نسخته */
var DEVICE_KEYS = { 'bassam_session_v1':1, 'bslg_v1':1, 'bassam_theme':1, 'bassam_active_dept_v1':1, 'bassam_fresh_login_v1':1 };
/* «آخر صفحة مفتوحة» (bassam_page_v1:…) تفضيلُ جهاز كذلك — لا يُخزَّن ولا يُحقن */
/* R187: و«مجموعات | قائمة» في الجدول الشهري (bassam_st_grp_v1، لكل إدارة) تفضيلُ عرضٍ لهذا الجهاز كذلك */
function isDeviceKey(k) { return !!DEVICE_KEYS[k] || /(^|:)bassam_page_v1:/.test(String(k)) || /(^|:)bassam_st_grp_v1$/.test(String(k)); }
var PW_MIN = 6;
var WORKER_VER = '2026.10.09-148';
